static inline int32_t st_wrap(int32_t d) { while (d > 1800) d -= 3600; while (d < -1800) d += 3600; return d; }
static inline uint32_t st_term(int32_t d, uint32_t w) { if (d < 0) d = -d; if (d > 1000) d = 1000; return w * (uint32_t)(d * d); }

// e0, e1, e2: pitch at press 1, 2, 3. r1, r2: yaw at press 2 and 3 minus yaw at press 1. All in 0.1 deg.
// Copies the nearest row into *out and returns its cost (compare with ST_COST_MAX).
static inline uint32_t st_find(int16_t e0, int16_t r1, int16_t r2, int16_t e1, int16_t e2, StRow* out) {
  uint32_t best = 0xFFFFFFFFUL;
  StRow row;
  for (uint16_t i = 0; i < ST_N; i++) {
    memcpy_P(&row, &ST_TABLE[i], sizeof(StRow));
    uint32_t c = st_term((int32_t)e0 - row.e0, ST_W_ELEV) + st_term(st_wrap((int32_t)r1 - row.r1), ST_W_REL)
               + st_term(st_wrap((int32_t)r2 - row.r2), ST_W_REL) + st_term((int32_t)e1 - row.e1, ST_W_ELEV)
               + st_term((int32_t)e2 - row.e2, ST_W_ELEV);
    if (c < best) { best = c; *out = row; }
  }
  return best;
}
